function formatJalali(iso){const d=parseIso(iso);return d?jalaliLongFormatter.format(d):"—";}
function formatJalaliInput(iso){const p=jalaliParts(iso);return p?toPersianDigits(String(p.year).padStart(4,"0")+"/"+String(p.month).padStart(2,"0")+"/"+String(p.day).padStart(2,"0")):"";}
function jalaliToGregorian(jy,jm,jd){let year=jy+1595;let days=-355668+(365*year)+(Math.floor(year/33)*8)+Math.floor(((year%33)+3)/4)+jd+(jm<7?(jm-1)*31:((jm-7)*30)+186);let gy=400*Math.floor(days/146097);days%=146097;if(days>36524){gy+=100*Math.floor(--days/36524);days%=36524;if(days>=365)days++;}gy+=4*Math.floor(days/1461);days%=1461;if(days>365){gy+=Math.floor((days-1)/365);days=(days-1)%365;}let gd=days+1;const leap=(gy%4===0&&gy%100!==0)||gy%400===0;const md=[0,31,leap?29:28,31,30,31,30,31,31,30,31,30,31];let gm=1;while(gm<=12&&gd>md[gm]){gd-=md[gm];gm++;}return{year:gy,month:gm,day:gd};}
