function normalizeState(raw){const base=defaultState();if(!raw||typeof raw!=="object")return base;const car=raw.vehicle&&typeof raw.vehicle==="object"?raw.vehicle:{};base.vehicle={label:cleanText(car.label,45)||base.vehicle.label,model:cleanText(car.model,60),year:cleanText(car.year,4),plate:cleanText(car.plate,20),odometer:clampNumber(car.odometer,0)};base.entries=Array.isArray(raw.entries)?raw.entries.map(normalizeEntry).filter(Boolean):[];base.documents=Array.isArray(raw.documents)?raw.documents.map(normalizeDocument).filter(Boolean):[];return base;}
