function renderExpenses(){const serviceItems=state.entries.filter(function(e){return e.cost>0;}).map(function(e){return{kind:"service",date:e.date,entry:e};}),docItems=state.documents.filter(function(d){return d.cost>0;}).map(function(d){return{kind:"document",date:d.kind==="insurance"?(d.paymentDate||d.startDate):d.inspectionDate,document:d};}),all=serviceItems.concat(docItems).sort(function(a,b){return String(b.date||"").localeCompare(String(a.date||""));});document.querySelector("#all-cost-stat").textContent=formatMoney(allCosts());document.querySelector("#expenses-list").innerHTML=all.length?all.map(function(x){return x.kind==="service"?renderExpenseRow(x.entry):renderDocumentExpense(x.document);}).join(""):renderEmpty("هزینه‌ای ثبت نشده","هزینهٔ قطعه و اجرت را هنگام ثبت وارد کنید تا جمع کل نمایش داده شود.","ثبت سرویس","add-service");}
