function readFileText(file){if(file&&typeof file.text==="function")return file.text();return new Promise(function(resolve,reject){const reader=new FileReader();reader.onload=function(){resolve(String(reader.result||""));};reader.onerror=function(){reject(reader.error||new Error("خواندن فایل ناموفق بود."));};reader.readAsText(file);});}
function validPhotoData(value){return typeof value==="string"&&/^data:image\/(jpeg|png|webp);base64,/.test(value)&&value.length<=MAX_PHOTO_DATA_LENGTH;}
async function importBackup(file){try{const raw=JSON.parse(await readFileText(file));if(!validBackup(raw))throw new Error("invalid");const source=raw.state||raw,imported=normalizeState(source),photoIds=new Set(imported.entries.concat(imported.documents).map(function(item){return item.photoId;}).filter(Boolean));let oldPhotos=[];try{oldPhotos=await idbGetAll();}catch(error){}let incoming=[];if(Array.isArray(raw.photos)){raw.photos.forEach(function(photo){if(photo&&typeof photo.id==="string"&&photoIds.has(photo.id)&&validPhotoData(photo.dataUrl))incoming.push({id:photo.id,dataUrl:photo.dataUrl});});}else{incoming=oldPhotos.filter(function(photo){return photoIds.has(photo.id);});}const validIds=new Set(incoming.map(function(photo){return photo.id;}));imported.entries.forEach(function(entry){if(entry.photoId&&!validIds.has(entry.photoId))entry.photoId=null;});imported.documents.forEach(function(doc){if(doc.photoId&&!validIds.has(doc.photoId))doc.photoId=null;});if(!window.confirm("اطلاعات این دستگاه با نسخهٔ پشتیبان جایگزین شود؟ سوابق: "+formatNumber(imported.entries.length)+" · مدارک: "+formatNumber(imported.documents.length)+" · عکس‌ها: "+formatNumber(incoming.length)))return;try{if(Array.isArray(raw.photos)||incoming.length||oldPhotos.length)await idbReplaceAll(incoming);}catch(error){showToast("بازیابی عکس‌ها ممکن نشد؛ اطلاعات فعلی تغییر نکرد.");return;}const oldState=state;state=imported;if(!saveState()){state=oldState;try{if(oldPhotos.length||incoming.length)await idbReplaceAll(oldPhotos);}catch(error){}return;}render();showToast("نسخهٔ پشتیبان بازیابی شد.");}catch(error){showToast("این فایل، نسخهٔ پشتیبان معتبر سرویس‌نگار نیست.");}}
function setView(view){if(["dashboard","services","insurance","inspection","expenses"].indexOf(view)<0)return;activeView=view;document.querySelectorAll(".tab-button").forEach(function(button){const active=button.dataset.view===view;button.classList.toggle("is-active",active);button.setAttribute("aria-selected",active?"true":"false");});document.querySelectorAll(".view-panel").forEach(function(panel){panel.hidden=panel.id!==view+"-view";});}
function handleDocumentClick(event){const button=event.target.closest("button");if(!button)return;if(button.id==="theme-toggle"){toggleTheme();return;}if(button.dataset.calendar){openCalendarPicker(button.dataset.calendar);return;}if(button.dataset.kmLatest){setKmInput(button.dataset.kmLatest,maxRecordedKm());return;}if(button.dataset.kmTarget){handleKmButton(button);return;}if(button.dataset.view||button.dataset.openView){setView(button.dataset.view||button.dataset.openView);return;}if(button.id==="add-service-top"||button.id==="add-service-history"||button.id==="add-service-reminder"||button.dataset.action==="add-service"){pendingDueAdvanceId=null;openServiceDialog(null);return;}if(button.id==="edit-vehicle-button"){openVehicleDialog();return;}if(button.id==="add-insurance-button"||button.id==="add-insurance-reminder"){openDocumentDialog("insurance","third_party",null);return;}if(button.id==="add-inspection-button"||button.id==="add-inspection-reminder"){openDocumentDialog("inspection","",null);return;}if(button.id==="cancel-vehicle-dialog"||button.id==="close-vehicle-dialog"){closeDialog(vehicleDialog);return;}if(button.id==="cancel-service-dialog"||button.id==="close-service-dialog"){pendingDueAdvanceId=null;closeDialog(serviceDialog);return;}if(button.id==="cancel-document-dialog"||button.id==="close-document-dialog"){closeDialog(documentDialog);return;}if(button.id==="close-photo-dialog"){closeDialog(photoViewDialog);return;}if(button.id==="view-existing-photo"){const image=document.querySelector("#existing-photo-preview");if(image.src)openPhotoViewer(image.src,"عکس فاکتور سرویس");return;}if(button.id==="view-existing-document-photo"){const image=document.querySelector("#document-existing-photo-preview");if(image.src)openPhotoViewer(image.src,"عکس مدرک");return;}if(button.id==="remove-existing-photo"){photoFlags.service.remove=true;document.querySelector("#existing-photo-wrap").hidden=true;showToast("عکس هنگام ذخیره برداشته می‌شود.");return;}if(button.id==="remove-existing-document-photo"){photoFlags.document.remove=true;document.querySelector("#document-existing-photo-wrap").hidden=true;showToast("عکس هنگام ذخیره برداشته می‌شود.");return;}if(button.id==="backup-button"){exportBackup();return;}if(button.id==="restore-button"){document.querySelector("#restore-file").click();return;}if(button.dataset.action==="complete-due"){openServiceForReminder(button.dataset.id);return;}if(button.dataset.action==="renew-insurance"){const oldDocument=state.documents.find(function(item){return item.id===button.dataset.id;});if(oldDocument&&oldDocument.kind==="insurance")openDocumentDialog("insurance",oldDocument.insuranceType,null,oldDocument.customInsuranceType||"");return;}if(button.dataset.action==="add-document"){openDocumentDialog(button.dataset.kind,button.dataset.subtype,null);return;}if(button.dataset.action==="edit-document"){const doc=state.documents.find(function(item){return item.id===button.dataset.id;});if(doc)openDocumentDialog(doc.kind,doc.insuranceType,doc.id);return;}if(button.dataset.action==="delete-document"){const doc=state.documents.find(function(item){return item.id===button.dataset.id;});if(doc&&window.confirm("این مدرک از دفترچه حذف شود؟")){const oldState=state;state={version:DATA_VERSION,vehicle:state.vehicle,entries:state.entries,documents:state.documents.filter(function(item){return item.id!==doc.id;})};if(saveState()){if(doc.photoId)deletePhoto(doc.photoId).catch(function(){});render();showToast("مدرک حذف شد.");}else state=oldState;}return;}if(button.dataset.action==="view-photo"){viewSavedPhoto(button.dataset.id);return;}if(button.dataset.action==="edit-entry"){pendingDueAdvanceId=null;openServiceDialog(button.dataset.id);return;}if(button.dataset.action==="delete-entry"){const entry=state.entries.find(function(item){return item.id===button.dataset.id;});if(entry&&window.confirm("سابقهٔ «"+(entry.part||entry.type)+"» حذف شود؟")){const oldState=state;state={version:DATA_VERSION,vehicle:state.vehicle,entries:state.entries.filter(function(item){return item.id!==entry.id;}),documents:state.documents};if(saveState()){if(entry.photoId)deletePhoto(entry.photoId).catch(function(){});render();showToast("سابقه حذف شد.");}else state=oldState;}return;}}
function registerEventHandlers(){document.addEventListener("click",handleDocumentClick);vehicleForm.addEventListener("submit",handleVehicleSubmit);serviceForm.addEventListener("submit",handleServiceSubmit);documentForm.addEventListener("submit",handleDocumentSubmit);documentKindSelect.addEventListener("change",toggleDocumentFields);document.querySelector("#parts-cost").addEventListener("input",updateServiceCostPreview);document.querySelector("#labor-cost").addEventListener("input",updateServiceCostPreview);document.querySelector("#service-photo").addEventListener("change",function(){handlePhotoSelect("service");});document.querySelector("#document-photo").addEventListener("change",function(){handlePhotoSelect("document");});document.querySelector("#restore-file").addEventListener("change",function(event){const file=event.target.files&&event.target.files[0];if(file)importBackup(file);event.target.value="";});datePickerEvents();}
function bootServiceNegar(){initServiceTypes();registerEventHandlers();let theme="dark";try{theme=localStorage.getItem(THEME_KEY)||"dark";}catch(error){}updateTheme(theme);render();if("serviceWorker" in navigator)window.addEventListener("load",function(){navigator.serviceWorker.register("/sw.js").catch(function(){showToast("فعال‌سازی حالت آفلاین در این مرورگر انجام نشد.");});});}
let pendingDueAdvanceId=null;
async function openServiceForReminder(id){const entry=state.entries.find(function(e){return e.id===id;});if(!entry)return;pendingDueAdvanceId=id;openServiceDialog(null,{type:entry.type,part:entry.part,brand:entry.brand});}
bootServiceNegar();
